using Microsoft.Win32;namespace SobhanNotificationHub.Services;public static class StartupService{private const string Key=@"Software\Microsoft\Windows\CurrentVersion\Run";private const string Name="SobhanNotificationHub";public static bool IsEnabled{get{using var k=Registry.CurrentUser.OpenSubKey(Key);return k?.GetValue(Name) is not null;}}public static void Set(bool enabled){using var k=Registry.CurrentUser.CreateSubKey(Key);if(enabled)k.SetValue(Name,$"\"{Environment.ProcessPath}\" --background");else k.DeleteValue(Name,false);}}
